import { EventStream, type AssistantMessage, type AssistantMessageEvent, type Message, type Model } from "@earendil-works/pi-ai/compat";
import { agentLoop } from "@earendil-works/pi-agent";
import type { AgentContext, AgentEvent, AgentLoopConfig, AgentMessage } from "@earendil-works/pi-agent";
import { afterEach, describe, expect, it, vi } from "vitest";

it("keeps a recovery image, details, and error flag in the actual agent-loop tool result", async () => {
	const f = fixture();
	await f.handlers.get("session_start")?.({}, f.ctx);
	const image = { type: "image" as const, data: "YQ==", mimeType: "image/png" };
	const details = { observation: "fresh", computer: { failed: true, workflow: "ready" } };
	setup.execute.mockResolvedValue({ content: [{ type: "text", text: "effect unverified" }, image], details, isError: true });
	const tool = f.tools.get("computer_click")!;
	const context: AgentContext = { systemPrompt: "", messages: [], tools: [tool] };
	const model: Model<"openai-responses"> = {
		id: "mock", name: "mock", api: "openai-responses", provider: "openai", baseUrl: "https://example.invalid",
		reasoning: false, input: ["text", "image"], cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
		contextWindow: 8192, maxTokens: 2048,
	};
	const usage = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } };
	let turn = 0;
	const config: AgentLoopConfig = {
		model,
		convertToLlm: (messages) => messages.filter((message) => ["user", "assistant", "toolResult"].includes(message.role)) as Message[],
		afterToolCall: async ({ toolCall, args, result, isError }) => {
			const override = await f.handlers.get("tool_result")?.({ toolName: toolCall.name, toolCallId: toolCall.id,
				input: args, content: result.content, details: result.details, isError });
			return { content: result.content, details: result.details, ...(override as { isError?: boolean } | undefined) };
		},
	};
	const stream = agentLoop([{ role: "user", content: "click", timestamp: Date.now() }], context, config, undefined, () => {
		const output = new EventStream<AssistantMessageEvent, AssistantMessage>(
			(event) => event.type === "done" || event.type === "error",
			(event) => event.type === "done" ? event.message : event.error,
		);
		const content: AssistantMessage["content"] = turn++ === 0
			? [{ type: "toolCall", id: "click-1", name: "computer_click", arguments: { desktop: true, foreground: true, observation: "prior", x: 1, y: 1 } }]
			: [{ type: "text", text: "done" }];
		queueMicrotask(() => output.push({ type: "done", reason: content[0].type === "toolCall" ? "toolUse" : "stop", message: {
			role: "assistant", content, api: "openai-responses", provider: "openai", model: "mock", usage,
			stopReason: content[0].type === "toolCall" ? "toolUse" : "stop", timestamp: Date.now(),
		} }));
		return output;
	});
	const events: AgentEvent[] = [];
	for await (const event of stream) events.push(event);
	const recorded = events.filter((event) => event.type === "message_end" && event.message.role === "toolResult");
	expect(recorded).toHaveLength(1);
	expect(recorded[0].message).toMatchObject({ isError: true, details,
		content: [{ text: "effect unverified" }, image] });
	expect(setup.execute).toHaveBeenCalledTimes(1);
	expect(setup.close).not.toHaveBeenCalled();
	await f.handlers.get("session_shutdown")?.();
});
